import { useState, type FormEvent } from 'react';
import { Button, Input, Stack, Text, useToast } from '@jinx-ui/react';

export default function SubscribeForm() {
  const [email, setEmail] = useState('');
  const toast = useToast();

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    const address = email.trim();
    if (!address) return;

    setEmail('');
    toast.show({
      title: 'Готово',
      description: `Письмо со ссылкой на подтверждение отправлено на ${address}.`,
      variant: 'success',
      placement: 'bottom-end',
    });
  };

  return (
    <form onSubmit={handleSubmit} style={{ maxWidth: 'var(--jx-size-form-md)' }}>
      <Stack direction="column" gap="var(--jx-space-4)">
        <Text as="h2" size="lg" weight="semibold">
          Подписка на рассылку
        </Text>
        <Stack direction="row" gap="var(--jx-space-2)" align="end">
          <Input
            type="email"
            name="email"
            label="Электронная почта"
            placeholder="you@example.com"
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            required
          />
          <Button type="submit" variant="primary" disabled={!email.trim()}>
            Подписаться
          </Button>
        </Stack>
      </Stack>
    </form>
  );
}

